function body(sh,start,rows){if(!rows.length)return;sh.getRange(`A${start}:${col(rows[0].length-1)}${start+rows.length-1}`).values=rows;for(let i=0;i<rows.length;i++)if(i%2===0)sh.getRange(`A${start+i}:${col(rows[i].length-1)}${start+i}`).format.fill='#EFF3F8';}
