function lines(sh,start,text,width=135){let row=start;for(const paragraph of text.split('\n')){let line='';for(const word of paragraph.split(' ')){if((line+' '+word).length>width){sh.getRange(`A${row++}`).values=[[line]];line=word}else line+=(line?' ':'')+word;}if(line)sh.getRange(`A${row++}`).values=[[line]];}return row;}
